  border-bottom:1px solid var(--grid);
  background:var(--panel2);
}

.legend-grid{
  display:flex;
  flex-wrap:wrap;
  gap:8px 12px;
}

.legend-item{
  display:flex;
  align-items:center;
  gap:8px;
  font-size:12px;
  color:var(--muted);
  white-space:nowrap;
}

.legend-swatch{
  width:10px;
  height:10px;
  border-radius:3px;
  border:1px solid rgba(255,255,255,0.28);
}

#chart-wrap{
  position:relative;
  flex:1 1 auto;
}

#bubble-svg{
  width:100%;
  height:100%;
  display:block;
}

.node circle{
  stroke:rgba(255,255,255,0.22);
  stroke-width:1;
}

.node.selected circle{
  stroke:var(--accent);
  stroke-width:3;
}

.node text{
  font-size:11px;
  font-weight:700;
  fill:rgba(255,255,255,0.92);
  pointer-events:none;
}

#tooltip{
  position:absolute;
  pointer-events:none;
  min-width:190px;
  max-width:260px;
  padding:10px 10px;
  border-radius:10px;
  background:rgba(15,23,48,0.96);
  border:1px solid rgba(122,162,255,0.45);
  box-shadow:0 10px 30px rgba(0,0,0,0.35);
}

#tooltip.hidden{ display:none; }

#tooltip .tkr{
  font-weight:800;
  font-size:13px;
}

#tooltip .name{
  margin-top:2px;
  color:var(--text);
  font-size:12px;
  line-height:1.25;
}

#tooltip .meta{
  margin-top:6px;
  color:var(--muted);
  font-size:12px;
}

#tooltip svg{
  margin-top:8px;
  display:block;
}

.table-wrap{
  overflow:auto;
  flex:1 1 auto;
}

table{
  width:100%;
  border-collapse:collapse;
}

thead th{
  position:sticky;
  top:0;
  background:var(--panel2);
  border-bottom:1px solid var(--grid);
  padding:10px 10px;
  text-align:left;
  font-size:12px;
  color:var(--muted);
  z-index:2;
}

tbody td{
  padding:10px 10px;
  border-bottom:1px solid rgba(35,48,87,0.55);
  font-size:13px;
}

tbody tr{
  cursor:pointer;
}

tbody tr:nth-child(2n){
  background:rgba(255,255,255,0.02);
}

tbody tr:hover{
  background:rgba(122,162,255,0.08);
}

tbody tr.selected{
  background:rgba(122,162,255,0.18);
  outline:1px solid rgba(122,162,255,0.35);
}

.marketcap{
  font-variant-numeric:tabular-nums;
  color:var(--text);
}

.small-muted{
  color:var(--muted);
  font-size:12px;
}
"}

