{"summary":"Generate visualization.js with embedded CSV data and interactive D3 chart", "command":"python3 - <<'PY'
import json
from pathlib import Path

desc_path = Path('/root/data/stock-descriptions.csv')
indiv_dir = Path('/root/data/indiv-stock')

desc_text = desc_path.read_text(encoding='utf-8')
price_map = {}
for p in sorted(indiv_dir.glob('*.csv')):
    price_map[p.stem] = p.read_text(encoding='utf-8')

js = f"""// Generated by OpenHands
(() => {{
  const DESCRIPTION_CSV_TEXT = {json.dumps(desc_text)};
  const PRICE_CSV_BY_TICKER = {json.dumps(price_map)};

  const parseDate = d3.timeParse('%Y-%m-%d');
  const priceCache = new Map();

  function formatMarketCap(value) {{
    const v = Number(value);
    if (!Number.isFinite(v) || v <= 0) return '—';

    const units = [
      [1e12, 'T'],
      [1e9, 'B'],
      [1e6, 'M'],
      [1e3, 'K'],
    ];

    for (const [u, s] of units) {{
      if (v >= u) {{
        const x = v / u;
        const decimals = x >= 100 ? 0 : x >= 10 ? 1 : 2;
        return d3.format(`.${{decimals}}f`)(x) + s;
      }}
    }}

    return d3.format(',.0f')(v);
  }}

  function getPriceSeries(ticker) {{
    if (priceCache.has(ticker)) return priceCache.get(ticker);
    const csvText = PRICE_CSV_BY_TICKER[ticker];
    if (!csvText) {{
      priceCache.set(ticker, null);
      return null;
    }}

    const rows = d3.csvParse(csvText);
    const series = rows
      .map(r => ({{
        date: parseDate(r.Date),
        close: Number(r.Close),
      }}))
      .filter(d => d.date && Number.isFinite(d.close));

    // Keep the chart lightweight: last ~260 trading days.
    const clipped = series.length > 260 ? series.slice(-260) : series;
    priceCache.set(ticker, clipped);
    return clipped;
  }}

  function drawSparkline(svg, series) {{
    const w = 170;
    const h = 46;
    const m = {{ top: 4, right: 6, bottom: 4, left: 6 }};

    svg.attr('width', w).attr('height', h).attr('viewBox', `0 0 ${{w}} ${{h}}`);
    svg.selectAll('*').remove();

    if (!series || series.length < 2) return;

    const x = d3.scaleTime()
      .domain(d3.extent(series, d => d.date))
      .range([m.left, w - m.right]);

    const y = d3.scaleLinear()
      .domain(d3.extent(series, d => d.close)).nice()
      .range([h - m.bottom, m.top]);

    const line = d3.line()
      .x(d => x(d.date))
      .y(d => y(d.close))
      .curve(d3.curveMonotoneX);

    svg.append('path')
      .attr('d', line(series))
      .attr('fill', 'none')
      .attr('stroke', 'rgba(122,162,255,0.95)')
      .attr('stroke-width', 1.6);

    const last = series[series.length - 1];
    svg.append('circle')
      .attr('cx', x(last.date))
      .attr('cy', y(last.close))
      .attr('r', 2.2)
      .attr('fill', 'rgba(233,238,255,0.95)');
  }}

  function sectorPositions(sectors, width, height) {{
    const n = sectors.length;
    const cols = Math.ceil(Math.sqrt(n));
    const rows = Math.ceil(n / cols);

    const cellX = Math.min(210, Math.max(150, width / (cols + 1)));
    const cellY = Math.min(190, Math.max(140, height / (rows + 1)));

    const gridW = (cols - 1) * cellX;
    const gridH = (rows - 1) * cellY;

    const startX = width / 2 - gridW / 2;
    const startY = height / 2 - gridH / 2;

    const pos = new Map();
    sectors.forEach((s, i) => {{
      const c = i % cols;
      const r = Math.floor(i / cols);
      pos.set(s, {{
        x: startX + c * cellX,
        y: startY + r * cellY,
      }});
    }});
    return pos;
  }}

  function main() {{
    const stocks = d3.csvParse(DESCRIPTION_CSV_TEXT, (d) => {{
      const mc = d.marketCap === '' || d.marketCap == null ? NaN : Number(d.marketCap);
      const isETF = !Number.isFinite(mc) || mc <= 0;

      return {{
        ticker: d.ticker,
        sector: (d.sector || 'Unknown').trim(),
        fullName: d['full name'] || d['full name '] || d['full name\r'] || '',
        marketCap: mc,
        isETF,
      }};
    }});

    const sectors = Array.from(new Set(stocks.map(d => d.sector))).sort(d3.ascending);

    const colors = [
      ...d3.schemeTableau10,
      ...d3.schemeSet3,
      ...d3.schemePaired,
    ];

    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(colors.slice(0, Math.max(sectors.length, 1)));

    // Legend
    const legend = d3.select('#legend-items');
    legend.selectAll('*').remove();
    legend.selectAll('.legend-item')
      .data(sectors)
      .join('div')
      .attr('class', 'legend-item')
      .call(sel => {{
        sel.append('span')
          .attr('class', 'legend-swatch')
          .style('background', d => color(d));
        sel.append('span').text(d => d);
      }});

    // Table
    const tbody = d3.select('#stock-table tbody');
    const rows = tbody.selectAll('tr')
      .data(stocks, d => d.ticker)
      .join('tr')
      .attr('data-ticker', d => d.ticker);

    rows.selectAll('*').remove();
    rows.on('click', (event, d) => setSelected(d.ticker, true));

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d.fullName);
    rows.append('td').text(d => d.sector);
    rows.append('td')
      .attr('class', 'marketcap')
      .text(d => formatMarketCap(d.marketCap));

    // Bubble chart
    const svg = d3.select('#bubble-svg');
    const wrap = document.getElementById('chart-wrap');
    const tooltip = d3.select('#tooltip');

    let nodeSel = null;
    let selectedTicker = null;

    function applySelectionStyles() {{
      if (nodeSel) {{
        nodeSel.classed('selected', d => d.ticker === selectedTicker);
      }}

      rows.classed('selected', d => d.ticker === selectedTicker);

      if (selectedTicker) {{
        const rowEl = tbody.select(`tr[data-ticker="${{selectedTicker}}"]`).node();
        if (rowEl) rowEl.scrollIntoView({{ block: 'nearest' }});
      }}
    }}

    function setSelected(ticker, fromUser) {{
      // Toggle selection if the same item is clicked.
      selectedTicker = (ticker && ticker === selectedTicker) ? null : ticker;
      applySelectionStyles();
    }}

    function showTooltip(event, d) {{
      if (d.isETF) return;

      tooltip.classed('hidden', false);
      tooltip.html(`
        <div class="tkr">${{d.ticker}}</div>
        <div class="name">${{d.fullName}}</div>
        <div class="meta">Sector: ${{d.sector}}</div>
        <svg class="spark"></svg>
      `);

      const series = getPriceSeries(d.ticker);
      drawSparkline(tooltip.select('svg.spark'), series);

      moveTooltip(event);
    }}

    function moveTooltip(event) {{
      const rect = wrap.getBoundingClientRect();
      const x = event.clientX - rect.left + 14;
      const y = event.clientY - rect.top + 14;
      tooltip.style('left', `${{x}}px`).style('top', `${{y}}px`);
    }}

    function hideTooltip() {{
      tooltip.classed('hidden', true);
    }}

    function render() {{
      const rect = wrap.getBoundingClientRect();
      const width = Math.max(520, Math.floor(rect.width));
      const height = Math.max(420, Math.floor(rect.height));

      svg.selectAll('*').remove();
      svg.attr('viewBox', `0 0 ${{width}} ${{height}}`);

      const caps = stocks.filter(d => !d.isETF).map(d => d.marketCap);
      const capExtent = d3.extent(caps);
      const rScale = d3.scaleSqrt()
        .domain(capExtent)
        .range([12, 58]);

      const etfRadius = 16;

      const nodes = stocks.map(d => ({{
        ...d,
        radius: d.isETF ? etfRadius : rScale(d.marketCap),
        x: width / 2 + (Math.random() - 0.5) * 40,
        y: height / 2 + (Math.random() - 0.5) * 40,
      }}));

      const sectorPos = sectorPositions(sectors, width, height);

      svg.append('rect')
        .attr('x', 0)
        .attr('y', 0)
        .attr('width', width)
        .attr('height', height)
        .attr('fill', 'transparent')
        .on('click', () => setSelected(null, true));

      const g = svg.append('g');

      nodeSel = g.selectAll('g.node')
        .data(nodes, d => d.ticker)
        .join('g')
        .attr('class', 'node')
        .style('cursor', 'pointer')
        .on('click', (event, d) => {{
          event.stopPropagation();
          setSelected(d.ticker, true);
        }})
        .on('mouseenter', (event, d) => showTooltip(event, d))
        .on('mousemove', (event, d) => {{ if (!d.isETF) moveTooltip(event); }})
        .on('mouseleave', () => hideTooltip());

      nodeSel.append('circle')
        .attr('r', d => d.radius)
        .attr('fill', d => color(d.sector))
        .attr('fill-opacity', 0.92);

      nodeSel.append('text')
        .attr('text-anchor', 'middle')
        .attr('dy', '0.35em')
        .text(d => d.ticker)
        .attr('font-size', d => Math.max(9, Math.min(14, d.radius * 0.6)));

      const sim = d3.forceSimulation(nodes)
        .force('center', d3.forceCenter(width / 2, height / 2))
        .force('charge', d3.forceManyBody().strength(-12))
        .force('x', d3.forceX(d => sectorPos.get(d.sector).x).strength(0.12))
        .force('y', d3.forceY(d => sectorPos.get(d.sector).y).strength(0.12))
        .force('collide', d3.forceCollide(d => d.radius + 1.6).strength(0.95).iterations(2));

      sim.on('tick', () => {{
        nodeSel.attr('transform', d => `translate(${{d.x}}, ${{d.y}})`);
      }});

      applySelectionStyles();
    }}

    let renderTimer = null;
    const ro = new ResizeObserver(() => {{
      window.clearTimeout(renderTimer);
      renderTimer = window.setTimeout(render, 80);
    }});

    ro.observe(wrap);
    render();
  }}

  if (document.readyState === 'loading') {{
    document.addEventListener('DOMContentLoaded', main);
  }} else {{
    main();
  }}
}})();
"""

out_path = Path('/root/output/js/visualization.js')
out_path.write_text(js, encoding='utf-8')
print('Wrote', out_path, 'size', out_path.stat().st_size)
PY"}

