  const priceCache = new Map();

  function formatMarketCap(value) {{
    const v = Number(value);
    if (!Number.isFinite(v) || v <= 0) return '—';

    const units = [
      [1e12, 'T'],
      [1e9, 'B'],
      [1e6, 'M'],
      [1e3, 'K'],
    ];

    for (const [u, s] of units) {{
      if (v >= u) {{
        const x = v / u;
        const decimals = x >= 100 ? 0 : x >= 10 ? 1 : 2;
        return d3.format(`.${{decimals}}f`)(x) + s;
      }}
    }}

    return d3.format(',.0f')(v);
  }}

  function getPriceSeries(ticker) {{
    if (priceCache.has(ticker)) return priceCache.get(ticker);
    const csvText = PRICE_CSV_BY_TICKER[ticker];
    if (!csvText) {{
      priceCache.set(ticker, null);
      return null;
    }}

    const rows = d3.csvParse(csvText);
    const series = rows
      .map(r => ({{
        date: parseDate(r.Date),
        close: Number(r.Close),
      }}))
      .filter(d => d.date && Number.isFinite(d.close));

    // Keep the chart lightweight: last ~260 trading days.
    const clipped = series.length > 260 ? series.slice(-260) : series;
    priceCache.set(ticker, clipped);
    return clipped;
  }}

  function drawSparkline(svg, series) {{
    const w = 170;
    const h = 46;
    const m = {{ top: 4, right: 6, bottom: 4, left: 6 }};

