    legend.selectAll('*').remove();
    legend.selectAll('.legend-item')
      .data(sectors)
      .join('div')
      .attr('class', 'legend-item')
      .call(sel => {{
        sel.append('span')
          .attr('class', 'legend-swatch')
          .style('background', d => color(d));
        sel.append('span').text(d => d);
      }});

    // Table
    const tbody = d3.select('#stock-table tbody');
    const rows = tbody.selectAll('tr')
      .data(stocks, d => d.ticker)
      .join('tr')
      .attr('data-ticker', d => d.ticker);

    rows.selectAll('*').remove();
    rows.on('click', (event, d) => setSelected(d.ticker, true));

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d.fullName);
    rows.append('td').text(d => d.sector);
    rows.append('td')
      .attr('class', 'marketcap')
      .text(d => formatMarketCap(d.marketCap));

    // Bubble chart
