    const wrap = document.getElementById('chart-wrap');
    const tooltip = d3.select('#tooltip');

    let nodeSel = null;
    let selectedTicker = null;

    function applySelectionStyles() {{
      if (nodeSel) {{
        nodeSel.classed('selected', d => d.ticker === selectedTicker);
      }}

      rows.classed('selected', d => d.ticker === selectedTicker);

      if (selectedTicker) {{
        const rowEl = tbody.select(`tr[data-ticker="${{selectedTicker}}"]`).node();
        if (rowEl) rowEl.scrollIntoView({{ block: 'nearest' }});
      }}
    }}

    function setSelected(ticker, fromUser) {{
      // Toggle selection if the same item is clicked.
      selectedTicker = (ticker && ticker === selectedTicker) ? null : ticker;
      applySelectionStyles();
    }}

    function showTooltip(event, d) {{
      if (d.isETF) return;

      tooltip.classed('hidden', false);
      tooltip.html(`
        <div class="tkr">${{d.ticker}}</div>
        <div class="name">${{d.fullName}}</div>
        <div class="meta">Sector: ${{d.sector}}</div>
        <svg class="spark"></svg>
      `);

      const series = getPriceSeries(d.ticker);
      drawSparkline(tooltip.select('svg.spark'), series);

      moveTooltip(event);
    }}

    function moveTooltip(event) {{
      const rect = wrap.getBoundingClientRect();
      const x = event.clientX - rect.left + 14;
      const y = event.clientY - rect.top + 14;
      tooltip.style('left', `${{x}}px`).style('top', `${{y}}px`);
    }}

    function hideTooltip() {{
      tooltip.classed('hidden', true);
    }}

    function render() {{
      const rect = wrap.getBoundingClientRect();
      const width = Math.max(520, Math.floor(rect.width));
      const height = Math.max(420, Math.floor(rect.height));

      svg.selectAll('*').remove();
      svg.attr('viewBox', `0 0 ${{width}} ${{height}}`);

      const caps = stocks.filter(d => !d.isETF).map(d => d.marketCap);
      const capExtent = d3.extent(caps);
      const rScale = d3.scaleSqrt()
        .domain(capExtent)
        .range([12, 58]);

      const etfRadius = 16;

