        y: height / 2 + (Math.random() - 0.5) * 40,
      }}));

      const sectorPos = sectorPositions(sectors, width, height);

      svg.append('rect')
        .attr('x', 0)
        .attr('y', 0)
        .attr('width', width)
        .attr('height', height)
        .attr('fill', 'transparent')
        .on('click', () => setSelected(null, true));

