        .attr('text-anchor', 'middle')
        .attr('dy', '0.35em')
        .text(d => d.ticker)
        .attr('font-size', d => Math.max(9, Math.min(14, d.radius * 0.6)));

      const sim = d3.forceSimulation(nodes)
        .force('center', d3.forceCenter(width / 2, height / 2))
        .force('charge', d3.forceManyBody().strength(-12))
        .force('x', d3.forceX(d => sectorPos.get(d.sector).x).strength(0.12))
        .force('y', d3.forceY(d => sectorPos.get(d.sector).y).strength(0.12))
        .force('collide', d3.forceCollide(d => d.radius + 1.6).strength(0.95).iterations(2));

      sim.on('tick', () => {{
        nodeSel.attr('transform', d => `translate(${{d.x}}, ${{d.y}})`);
      }});

      applySelectionStyles();
    }}

    let renderTimer = null;
    const ro = new ResizeObserver(() => {{
      window.clearTimeout(renderTimer);
      renderTimer = window.setTimeout(render, 80);
    }});

    ro.observe(wrap);
    render();
  }}

  if (document.readyState === 'loading') {{
    document.addEventListener('DOMContentLoaded', main);
  }} else {{
    main();
  }}
}})();
